import React, { useCallback, useImperativeHandle, forwardRef } from 'react'
import { Cascader } from 'antd'
import type { CascaderProps } from 'antd'
import { useAreaData } from '@/hooks/useAreaData'

export interface AreaCascaderRef {
  loadAreaData: (parentId?: number | null, requestLevel?: number) => Promise<Area.Option[]>
}

interface AreaCascaderProps {
  name?: string
  value?: string[]
  /** 选中变化回调，返回地区名称和ID */
  onChange?: (result: { labels: string[]; values: string[] }) => void
  placeholder?: string
  /** 是否启用异步加载模式，默认为 true */
  asyncMode?: boolean
  /** 初始加载的父级ID，默认为0（省级） */
  initialParentId?: number
  /** 组件大小 */
  size?: 'small' | 'middle' | 'large'
  /** 自定义样式 */
  styles?: React.CSSProperties
}

const AreaCascader = forwardRef<AreaCascaderRef, AreaCascaderProps>(
  (
    {
      name,
      value,
      onChange,
      placeholder = '请选择地区',
      asyncMode = true,
      initialParentId = 4744,
      size = 'middle',
      styles
    },
    ref
  ) => {
    const { options, loading, loadData, loadAreaData } = useAreaData({
      asyncMode,
      initialParentId
    })

    // 暴露 loadAreaData 方法给父组件
    useImperativeHandle(ref, () => ({
      loadAreaData
    }))

    // 判断是否为直辖市（根据 ID）
    const isMunicipality = useCallback((id: string | number): boolean => {
      const numId = typeof id === 'string' ? parseInt(id) : id
      // 直辖市 ID：1-北京, 2-上海, 3-天津, 4-重庆
      return [1, 2, 3, 4].includes(numId)
    }, [])

    // 处理级联选择变化
    const handleChange: CascaderProps<Area.Option>['onChange'] = useCallback(
      (
        selectedValues: (string | number)[],
        selectedOptions: { label: string; value: string | number }[]
      ) => {
        const labels = selectedOptions.map((option: { label: string }) => option.label)
        const values = selectedOptions.map((option: { value: string | number }) =>
          String(option.value)
        )

        if (!selectedValues || selectedValues.length === 0) {
          onChange?.({ labels: [], values: [] })
          return
        }

        // 直辖市三级结构处理
        if (selectedValues.length === 3 && isMunicipality(selectedOptions[0].value)) {
          // 直辖市：[省ID, 市ID, 区ID] -> 市ID与省ID相同
          // 转换为标准格式：[省ID, 省ID, 区ID]
          const expandedLabels = [
            selectedOptions[0].label,
            selectedOptions[1].label,
            selectedOptions[2].label
          ]
          const expandedValues = [
            String(selectedOptions[0].value),
            String(selectedOptions[0].value),
            String(selectedOptions[2].value)
          ]
          onChange?.({ labels: expandedLabels, values: expandedValues })
        } else {
          onChange?.({ labels, values })
        }
      },
      [onChange, isMunicipality]
    )

    return (
      <Cascader
        options={options}
        allowClear={false}
        placeholder={placeholder}
        loading={loading}
        loadData={asyncMode ? loadData : undefined}
        value={value}
        onChange={handleChange}
        changeOnSelect={false}
        displayRender={(labels: string[]) => labels.join(' / ')}
        size={size}
        style={styles}
        showSearch={{
          filter: (inputValue: string, path: Area.Option[]) =>
            path.some(option => option.label.toLowerCase().includes(inputValue.toLowerCase()))
        }}
      />
    )
  }
)

export default AreaCascader
